function makeV2MoleculeSet(lang){
  const out={};
  for(const id in MOLS_EN){
    const base=MOLS_EN[id];
    const curated=lang==='fr'?V2_MOLECULE_NAMES_FR:V2_MOLECULE_NAMES_ZH;
    out[id]=Object.assign({},base,{n:curated[id]||v2Text(base.n,lang),w:v2Text(base.w,lang),fa:v2Text(base.fa,lang)});
  }
  return out;
}
function makeV2ElementInfo(lang){
  const out={};
  for(const id in ELINFO_EN){
    const base=ELINFO_EN[id],curated=(ELEMENT_NAMES_I18N[lang]||{})[id];
    const name=lang==='fr'&&curated?curated.charAt(0).toLocaleUpperCase('fr-FR')+curated.slice(1):curated;
    out[id]=Object.assign({},base,{n:name||v2Text(base.n,lang),fa:v2Text(base.fa,lang)});
  }
  return out;
}
