function makeV2I18nPack(lang){
  const out={};
  for(const [key,value] of Object.entries(I18N.en)){
    out[key]=typeof value==='function'?((...args)=>v2Text(value(...args),lang)):v2DeepCopy(value,lang);
  }
  return out;
}
