function ml(tr,en,de,es,pt,ja,fr,zh){
  if(LANG==='fr')return fr!==undefined&&fr!==null?fr:v2Text(en,LANG);
  if(LANG==='zh')return zh!==undefined&&zh!==null?zh:v2Text(en,LANG);
  const values={tr:tr,en:en,de:de,es:es,pt:pt,ja:ja};
  return values[LANG]!==undefined&&values[LANG]!==null?values[LANG]:en;
}
