function releaseGameVisualLoadForMenu(){
  try{
    stopNearWinLayer();
    if(typeof PARTS!=='undefined')PARTS.length=0;
    if(typeof DUST!=='undefined')DUST.length=0;
    if(typeof clearMoleculeCompletionFx==='function')clearMoleculeCompletionFx();
    if(typeof mxNextMolTransitionTimer!=='undefined'&&mxNextMolTransitionTimer){clearTimeout(mxNextMolTransitionTimer);mxNextMolTransitionTimer=0;}
    const next=document.getElementById('mxNextMoleculeTransition');if(next){next.classList.remove('on','leave');next.style.display='none';}
    const entry=document.getElementById('levelTransition');if(entry){entry.classList.remove('on','mxOut');}
    const tool=document.getElementById('mxToolFx');if(tool)tool.remove();
    const snap=document.getElementById('mxCompletionSnap');if(snap)snap.remove();
    document.body.classList.remove('mxImpact');
    const frame=document.getElementById('boardFrame');if(frame)frame.classList.remove('mxCompletionHold');
    shake=0;bounce=0;nudge=0;movingWallAnimating=false;
    lastBoardFrame=lastGoalFrame=lastFxFrame=performance.now();
  }catch(e){console.warn('[stability] menu visual cleanup failed',e);}
}
function show(k){
  if(k!=='game'&&typeof completionResultTimer!=='undefined'&&completionResultTimer){
    clearTimeout(completionResultTimer);completionResultTimer=null;
  }
  if(k!=='game'){
    const bw=document.getElementById('bannerWrap');
    if(bw)bw.classList.remove('on','leaving','longName');
  }
  if(autoSolveInProgress&&k!=='game'){say(ml("Çözüm oynatımı bitene kadar oyun ekranında kal.","Stay on the game screen until the solution playback finishes.","Bleibe auf dem Spielbildschirm, bis die Lösungswiedergabe beendet ist.","Permanece en la pantalla de juego hasta que termine la reproducción de la solución.","Permaneça na tela do jogo até a reprodução da solução terminar.","解答の再生が終わるまでゲーム画面にいてください。"),'talk',2400,'glow');return;}
  if(screenTransitionLock||!scr[k])return;
  if(k==='game')resumeSolveClock('screen');else pauseSolveClock('screen');
  if(k!=='splash')cancelPendingMenuVoice();
  if(k!=='game')clearTutorialRuntime();
  screenTransitionLock=true;
  const current=Object.keys(scr).find(s=>scr[s].classList.contains('on'))||scrPrev;
  if(current===k){screenTransitionLock=false;return;}
  if(current==='game'&&k!=='game')releaseGameVisualLoadForMenu();
  const outgoing=scr[current],incoming=scr[k];
  document.body.classList.add('mxUiTransitioning');
  if(outgoing)outgoing.classList.add('mxLeaving');
  incoming.classList.add('mxEntering');
  setTimeout(()=>{
    screenTransitionLock=false;
    document.body.classList.remove('mxUiTransitioning');
    if(outgoing)outgoing.classList.remove('mxLeaving');
    incoming.classList.remove('mxEntering');
  },300);
  for(const s in scr)if(scr[s].classList.contains('on'))scrPrev=s;
  for(const s in scr)scr[s].classList.toggle('on',s===k);
  if(k!=='game')freshMenuTrack();
  if(k==='game')requestAnimationFrame(resize);
  if(k==='levels'){buildLevels();$('#lvCoins span:last-child').textContent=save.coins;}
  if(k==='collect')buildCollection();
  if(k==='lab')buildLab();
  if(k==='hof'){buildHof();refreshSpotlights();}
  if(k==='splash'){refreshSplash();startSplashConversation(true,260);scheduleMainMenuVoice('home',680);}
  else stopSplashConversation();
}
