  setTimeout(()=>moxyReact(Number(stars)>=3?'happy':'pop',true),240);
  setDrEPose(finale?'medal':(Number(stars)>=3?'victory':'clap'),finale?8200:(Number(stars)>=3?7200:6000),finale?9:(Number(stars)>=3?8:6),true);
  blink();
  setTimeout(tongue,180);
