  for(const w of movingWalls){if(grid[w.y])grid[w.y][w.x]=false;}
  state.forEach((st,i)=>{const w=movingWalls[i];if(!w)return;w.x=+st.x;w.y=+st.y;w.index=+st.index||0;w.anim=null;if(grid[w.y])grid[w.y][w.x]=true;});
