  if(moving&&!motionReduced()){
    bctx.globalAlpha=.34+.18*Math.sin(t/70);bctx.strokeStyle='#ffffff';bctx.lineWidth=Math.max(1,T*.018);rrect(bctx,px+T*.12,py+T*.12,T*.76,T*.76,Math.max(5,T*.1));bctx.stroke();
  }
