function duelFormatTime(sec){
  sec=Math.max(0,Number(sec)||0);const m=Math.floor(sec/60),r=sec-m*60;
  return String(m).padStart(2,'0')+':'+r.toFixed(1).padStart(4,'0');
}
function duelEsc(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function duelPoolFor(kind){
  if(kind==='medium')return {kind,min:40,max:99};
  if(kind==='hard')return {kind,min:120,max:LEVELS.length-1};
  return {kind:'mixed',min:40,max:LEVELS.length-1};
}
// Duel runs deliberately disable campaign-only board systems such as portals,
// pressure doors and breakable/moving walls. Never draw a campaign level whose
// certified route depends on one of those systems: otherwise the same level can
// become a different (or impossible) puzzle inside Duel. Special-atom campaign
// levels are also kept out of the shared duel pool so Classic/Crystal/Chain/
// Reactor all start from the same verified plain sliding rules. R74 audit:
// 203/301 campaign levels are safe by this definition; 62 are from levels
// 206–301, so the old 205 cap remains removed without admitting incompatible
// Grand Master mechanics.
function isDuelBaseLevelSafe(levelIndex){
  const i=Math.floor(Number(levelIndex)),L=LEVELS[i];
  if(!Number.isInteger(i)||!L||!(L.fs||[]).length)return false;
  if(HAMMER_LEVELS.has(i)||Object.prototype.hasOwnProperty.call(PORTAL_LAYOUTS,i)||ONE_WAY_LEVELS.has(i)||MOVING_WALL_LEVELS.has(i)||PRESSURE_DOOR_LEVELS.has(i)||FRAGILE_ATOM_LEVELS.has(i)||LINKED_ATOM_LEVELS.has(i))return false;
  if(['ow','bw','pt','mw','pd','linked','fragile'].some(k=>Array.isArray(L[k])&&L[k].length))return false;
  if((L.a||[]).some(a=>Array.isArray(a)&&a.slice(3).some(Boolean)))return false;
  return true;
}
function isDuelLevelEligibleForType(levelIndex,gameType='classic'){
  if(!isDuelBaseLevelSafe(levelIndex))return false;
  if(gameType==='chain'&&!isChainLevelEligible(levelIndex))return false;
  if(gameType==='reactor'&&!isReactorLevelEligible(levelIndex))return false;
  return true;
}
function duelEligibleLevelIndexes(pool,exclude=[],gameType='classic'){
  const blocked=new Set((exclude||[]).map(Number)),out=[],max=Math.min(pool.max,LEVELS.length-1);
  for(let i=pool.min;i<=max;i++){
    if(blocked.has(i)||!isDuelLevelEligibleForType(i,gameType))continue;
    out.push(i);
  }
  return out;
}
function randomDuelLevelFromPool(pool,exclude=[],gameType='classic'){
  const list=duelEligibleLevelIndexes(pool,exclude,gameType);
  if(list.length)return list[Math.floor(Math.random()*list.length)];
  // Defensive fallback for a future very narrow custom pool. Prefer another
  // verified-safe level over silently reintroducing an incompatible board.
  const safe=duelEligibleLevelIndexes(pool,[],gameType);
  return safe.length?safe[Math.floor(Math.random()*safe.length)]:null;
}
const DUEL_RECENT_LEVEL_KEY='mx_duel_recent_levels_v1';
const DUEL_RECENT_LEVEL_LIMIT=18;
function duelRecentLevels(){
  try{
    const raw=JSON.parse(localStorage.getItem(DUEL_RECENT_LEVEL_KEY)||'[]');
    return Array.isArray(raw)?raw.map(Number).filter(Number.isInteger).slice(-DUEL_RECENT_LEVEL_LIMIT):[];
  }catch(e){return [];}
}
function rememberDuelLevels(levels){
  try{
    const next=duelRecentLevels();
    for(const level of (Array.isArray(levels)?levels:[])){
      const n=Math.floor(Number(level));if(!Number.isInteger(n))continue;
      const at=next.indexOf(n);if(at>=0)next.splice(at,1);next.push(n);
    }
    localStorage.setItem(DUEL_RECENT_LEVEL_KEY,JSON.stringify(next.slice(-DUEL_RECENT_LEVEL_LIMIT)));
  }catch(e){}
}
function duelBuildLevels(pool){
  const recent=new Set(duelRecentLevels()),fresh=[],fallback=[];
  for(let i=pool.min;i<=Math.min(pool.max,LEVELS.length-1);i++){
    if(!isDuelBaseLevelSafe(i))continue;
    (recent.has(i)?fallback:fresh).push(i);
  }
  const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
  shuffle(fresh);shuffle(fallback);
  // Prefer levels not seen in the most recent duels. Only fall back if a very
  // narrow future pool cannot provide enough unique rounds.
  return fresh.concat(fallback).slice(0,DUEL_MAX_ROUNDS);
}
function duelBuildGameTypes(kind){
  if(kind==='classic')return ['classic','classic','classic'];
  if(kind==='crystal')return ['crystal','crystal','crystal'];
  if(kind==='chain')return ['chain','chain','chain'];
  if(kind==='reactor')return ['reactor','reactor','reactor'];
  const types=['classic','crystal','chain','reactor'];
  for(let i=types.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[types[i],types[j]]=[types[j],types[i]];}
  return types.slice(0,DUEL_MAX_ROUNDS);
}
function duelMakeRounds(levels,gameKind,pool){
  const types=duelBuildGameTypes(gameKind),used=[],recent=duelRecentLevels();
  const rounds=levels.map((candidate,i)=>{
    let level=candidate,exclude=recent.concat(used);
    if(types[i]==='chain'&&!isChainLevelEligible(level))level=randomDuelLevelFromPool(pool||duelPoolFor('mixed'),exclude,'chain');
    if(types[i]==='reactor'&&!isReactorLevelEligible(level))level=randomDuelLevelFromPool(pool||duelPoolFor('mixed'),exclude,'reactor');
    if(used.includes(level)||recent.includes(level)){
      level=randomDuelLevelFromPool(pool||duelPoolFor('mixed'),exclude,types[i]);
    }
    // Final duplicate/safety guard for all duel types. Keep the replacement
    // eligible for the selected round mode as well (especially Chain/Reactor).
    if(!Number.isInteger(level)||used.includes(level)||!isDuelLevelEligibleForType(level,types[i])){
      const activePool=pool||duelPoolFor('mixed');
      let choices=duelEligibleLevelIndexes(activePool,exclude,types[i]);
      if(!choices.length)choices=duelEligibleLevelIndexes(activePool,used,types[i]);
      if(choices.length)level=choices[Math.floor(Math.random()*choices.length)];
    }
    used.push(level);
    return {level,gameType:types[i],crystals:types[i]==='crystal'?buildCrystalLayout(level):null,chainPlan:types[i]==='chain'?buildChainPlan(level):null,reactorPlan:types[i]==='reactor'?buildReactorPlan(level):null,results:[null,null],winner:null};
  });
  rememberDuelLevels(rounds.map(r=>r.level));
  return rounds;
}
function duelCurrentRound(){return duelState&&duelState.rounds?duelState.rounds[duelState.round]:null;}
function duelStyleTitle(index){const st=duelState&&duelState.playerStyles&&duelState.playerStyles[index];if(!st||!st.title)return '';const row=duelTitleRows().find(x=>x.id===st.title);return row?' <small>· '+duelEsc(dyn6(row.tr,row.en))+'</small>':'';}
function duelStyleFrameClass(index){const st=duelState&&duelState.playerStyles&&duelState.playerStyles[index],f=st&&DUEL_FRAMES.find(x=>x.id===st.frame);return f?f.css:'frame-bronze';}
