  // centroid -> screen coords
  const r=board.getBoundingClientRect();
  const cx=r.left+atoms.reduce((s,a)=>s+a.x+0.5,0)/atoms.length*T;
  const cy=r.top+atoms.reduce((s,a)=>s+a.y+0.5,0)/atoms.length*T;
