function mergeCloudData(target,cloud){
  target=ensureResearchState(Object.assign(defaultSave(),target||{}));cloud=cloud||{};
  const core=window.MXSyncCore;
  if(core&&typeof core.mergeProfiles==='function'){
    const merged=core.mergeProfiles(target,cloud,{settings:'right',identity:'right',now:new Date()});
    merged.autoGuest=false;
    return ensureResearchState(Object.assign(defaultSave(),merged));
  }
  // Safe compatibility fallback; V3.8.3 normally uses the shared merge core.
  const cloudStars=cloud.stars&&typeof cloud.stars==='object'?cloud.stars:{};
  for(const k in cloudStars)target.stars[k]=Math.max(Number(target.stars[k])||0,Number(cloudStars[k])||0);
  if(cloud.bestMoves)for(const k in cloud.bestMoves){const cv=Number(cloud.bestMoves[k]),lv=Number(target.bestMoves[k]);if(cv>0&&(!lv||cv<lv))target.bestMoves[k]=cv;}
  target.cur=Math.max(Number(target.cur)||0,Number(cloud.cur)||0);
  if(cloud.disc)for(const k in cloud.disc)if(cloud.disc[k])target.disc[k]=1;
  if(cloud.achv)for(const k in cloud.achv)if(cloud.achv[k])target.achv[k]=1;
  if(cloud.speedRuns)for(const k in cloud.speedRuns){const cv=Number(cloud.speedRuns[k]),lv=Number(target.speedRuns[k]);if(cv>0&&(!lv||cv<lv))target.speedRuns[k]=cv;}
  target.coins=Math.max(Number(target.coins)||0,Number(cloud.coins)||0,Number(cloud.verifiedCoins)||0);
  target.maxCoins=Math.max(Number(target.maxCoins)||0,Number(cloud.maxCoins)||0,target.coins);
  if(cloud.researchLevels)for(const k in cloud.researchLevels)target.researchLevels[k]=Math.max(Number(target.researchLevels[k])||0,Number(cloud.researchLevels[k])||0);
  if(cloud.researchAchievements)for(const k in cloud.researchAchievements)target.researchAchievements[k]=Math.max(Number(target.researchAchievements[k])||0,Number(cloud.researchAchievements[k])||0);
  if(cloud.researchBonuses)for(const k in cloud.researchBonuses)target.researchBonuses[k]=Math.max(Number(target.researchBonuses[k])||0,Number(cloud.researchBonuses[k])||0);
  if(cloud.bonusClaims)for(const k in cloud.bonusClaims)if(cloud.bonusClaims[k])target.bonusClaims[k]=1;
  if(cloud.dailyScores)for(const k in cloud.dailyScores)target.dailyScores[k]=Math.max(Number(target.dailyScores[k])||0,Number(cloud.dailyScores[k])||0);
  target.duelRatedMatches=target.duelRatedMatches&&typeof target.duelRatedMatches==='object'?target.duelRatedMatches:{};if(cloud.duelRatedMatches)for(const k in cloud.duelRatedMatches)target.duelRatedMatches[k]=Math.max(Number(target.duelRatedMatches[k])||0,Number(cloud.duelRatedMatches[k])||0);
  target.duelRewards=target.duelRewards&&typeof target.duelRewards==='object'?target.duelRewards:{};if(cloud.duelRewards)for(const k in cloud.duelRewards)if(cloud.duelRewards[k])target.duelRewards[k]=1;
  target.duelRewardClaims=target.duelRewardClaims&&typeof target.duelRewardClaims==='object'?target.duelRewardClaims:{};if(cloud.duelRewardClaims)for(const k in cloud.duelRewardClaims)target.duelRewardClaims[k]=Math.max(Number(target.duelRewardClaims[k])||0,Number(cloud.duelRewardClaims[k])||0);
  if(cloud.activeDuelFrame)target.activeDuelFrame=String(cloud.activeDuelFrame).slice(0,40);if(cloud.activeDuelTitle!=null)target.activeDuelTitle=String(cloud.activeDuelTitle).slice(0,40);
  target.duelPeakRating=Math.max(Number(target.duelPeakRating)||800,Number(cloud.duelPeakRating)||800);target.duelBestStreak=Math.max(Number(target.duelBestStreak)||0,Number(cloud.duelBestStreak)||0);
  const calculated=researchMapSum(target.researchLevels)+researchMapSum(target.researchAchievements)+researchMapSum(target.researchBonuses)+researchMapSum(target.dailyScores);
  target.researchPoints=Math.max(calculated,Number(target.researchPoints)||0,Number(cloud.researchPoints)||0);
  if(cloud.playerName)target.playerName=String(cloud.playerName).slice(0,18);
  if(cloud.profileId)target.profileId=cloud.profileId;
  target.autoGuest=false;target.saveSchema=5;
  return ensureResearchState(target);
}

function cloudAuthoritativeProfile(local,cloud){
  // R31: first restore this Firebase account's synchronous device checkpoint.
  // Then perform the existing monotonic cloud merge. This makes an Apple UID's
  // newer local level survive even when Firestore still contains an older level.
  const vaultProfileId=(cloud&&cloud.profileId)||(local&&local.profileId)||'';
  local=mergeAccountProgressVault(local||{},vaultProfileId);
  // R29 progress-safety rule: cloud identity/settings may win, but campaign
  // progress must be monotonic. A delayed Firestore response from level N must
  // never overwrite levels N+1/N+2 already completed on this device.
  local=local&&typeof local==='object'?local:{};
  cloud=cloud&&typeof cloud==='object'?cloud:{};
  const core=window.MXSyncCore;
  if(core&&typeof core.mergeProfiles==='function'){
    const merged=core.mergeProfiles(local,cloud,{settings:'right',identity:'right',now:new Date(),includeBonus:true});
    const deviceLang=readDeviceLanguagePreference();if(deviceLang)merged.lang=deviceLang;
    merged.autoGuest=false;merged.saveSchema=5;
    return ensureResearchState(Object.assign(defaultSave(),merged));
  }
  // Compatibility fallback keeps the same max/union semantics.
  const merged=mergeCloudData(local,cloud);
  const deviceLang=readDeviceLanguagePreference();if(deviceLang)merged.lang=deviceLang;
  merged.autoGuest=false;merged.saveSchema=5;
  return ensureResearchState(Object.assign(defaultSave(),merged));
}

function normalizedPlayerName(value){
  const core=window.MXSyncCore;
  return core&&core.normalizeName?core.normalizeName(value):String(value||'').trim().toLowerCase().replace(/\s+/g,' ');
}

function accountProfileScope(){
  return String((accountState&&accountState.uid)||(window.MXCloud&&window.MXCloud.uid)||'guest').replace(/[^a-zA-Z0-9_-]/g,'_');
}
function timedProfileSet(kind){
  const key='mx_'+kind+'_profiles_r16_'+accountProfileScope();let raw={};
  try{raw=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch(e){}
  const now=Date.now(),maxAge=7*24*60*60*1000;let changed=false;
  for(const id of Object.keys(raw)){if(!id||now-Number(raw[id]||0)>maxAge){delete raw[id];changed=true;}}
  if(changed)try{localStorage.setItem(key,JSON.stringify(raw));}catch(e){}
  return {key,raw};
}
function updateTimedProfileSet(kind,profileId,on){
  if(!profileId)return;const box=timedProfileSet(kind);
  if(on)box.raw[profileId]=Date.now();else delete box.raw[profileId];
  try{localStorage.setItem(box.key,JSON.stringify(box.raw));}catch(e){}
}
function pendingProfileIds(){return new Set(Object.keys(timedProfileSet('pending').raw));}
function suppressedProfileIds(){return new Set(Object.keys(timedProfileSet('suppressed').raw));}
function markPendingProfileId(profileId){updateTimedProfileSet('pending',profileId,true);}
function clearPendingProfileId(profileId){updateTimedProfileSet('pending',profileId,false);}
function suppressCloudProfileId(profileId){updateTimedProfileSet('suppressed',profileId,true);clearPendingProfileId(profileId);}
function activeProfileIsPending(){return !!(save&&save.profileId&&pendingProfileIds().has(save.profileId));}
async function flushPendingActiveProfile(expectedEpoch){
  if(expectedEpoch!==undefined&&expectedEpoch!==profileContextEpoch)return false;
  if(!window.MXCloud||accountState.isAnonymous||!save||!save.profileId||!activeProfileIsPending())return true;
  const pid=save.profileId,snapshot=ensureResearchState(Object.assign(defaultSave(),save));
  const context=captureCloudOperationContext(pid);
  const merged=await window.MXCloud.saveProgressNow(snapshot,pid);
  if(saveResultWasSkipped(merged)||!cloudOperationContextIsCurrent(context))return false;
  if(!merged)return false;
  clearPendingProfileId(pid);
  markCloudSaveConfirmed(pid,context.uid);
  if((expectedEpoch===undefined||expectedEpoch===profileContextEpoch)&&save.profileId===pid)applyMergedCloudProfile(merged);
  return true;
}
async function syncActiveProfileSafely(expectedEpoch){
  try{
    if(expectedEpoch!==profileContextEpoch||!save||!save.profileId)return false;
    if(activeProfileIsPending())await flushPendingActiveProfile(expectedEpoch);
    if(expectedEpoch!==profileContextEpoch)return false;
    await syncFromCloud();return true;
  }catch(e){console.warn('[sync] active profile sync failed',e&&e.code||e);return false;}
}
async function reconcileAccountProfiles(){
  if(!window.MXCloud||accountState.isAnonymous)return false;
  if(accountReconcilePromise)return accountReconcilePromise;
  const startEpoch=profileContextEpoch,startAccountEpoch=accountContextEpoch,startUid=currentCloudAuthUid(),startId=save&&save.profileId,startKey=curProfile;
  const reconcileContextCurrent=()=>startEpoch===profileContextEpoch&&startAccountEpoch===accountContextEpoch&&startUid===currentCloudAuthUid();
  const priorSyncStatus=syncStatus;
  accountReconcilePromise=(async()=>{
    setSyncStatus('syncing');
    try{
      const listed=await window.MXCloud.listProfiles();
      if(!Array.isArray(listed))throw Object.assign(new Error('cloud/profile-list-unavailable'),{code:'cloud/profile-list-unavailable'});
      // The user may create/select another player while Firestore is responding.
      // Never apply the now-stale response to that new context.
      if(!reconcileContextCurrent())return false;
      const oldProfiles=profiles||{},pending=pendingProfileIds(),suppressed=suppressedProfileIds();
      const rows=listed.filter(r=>r&&r.profileId&&!suppressed.has(r.profileId));
      const rebuilt={};
      const addProfile=(profile,preferred)=>{
        if(!profile||!profile.profileId)return null;
        const existing=Object.keys(rebuilt).find(k=>(rebuilt[k]||{}).profileId===profile.profileId);if(existing)return existing;
        let key=String(preferred||profile.playerName||'Player').trim().slice(0,18)||'Player',n=2;
        while(rebuilt[key])key=(String(profile.playerName||preferred||'Player').slice(0,14)||'Player')+' '+(n++);
        rebuilt[key]=ensureResearchState(Object.assign(defaultSave(),profile));return key;
      };
      for(const cloud of rows){
        let local=null;
        for(const key of Object.keys(oldProfiles))if((oldProfiles[key]||{}).profileId===cloud.profileId){local=oldProfiles[key];break;}
        addProfile(cloudAuthoritativeProfile(local,cloud),cloud.playerName);
      }
      // Explicitly created New Game players are protected until their first write
      // is confirmed. They must not be discarded merely because listProfiles()
      // completed a moment before their new document appeared in Firestore.
      for(const key of Object.keys(oldProfiles)){
        const local=oldProfiles[key]||{},pid=local.profileId;
        if(pid&&pending.has(pid)&&!suppressed.has(pid))addProfile(local,key);
      }
      if(!rows.length&&startKey&&oldProfiles[startKey]){
        const local=ensureResearchState(Object.assign(defaultSave(),oldProfiles[startKey]));
        if(!local.profileId)local.profileId=genProfileId();
        local.playerName=local.playerName||startKey;local.saveSchema=5;
        const written=await window.MXCloud.saveProgressNow(local,local.profileId);
        if(!reconcileContextCurrent())return false;
        if(written&&!saveResultWasSkipped(written)){clearPendingProfileId(local.profileId);markCloudSaveConfirmed(local.profileId,startUid);addProfile(cloudAuthoritativeProfile(local,written),local.playerName);}
        else addProfile(local,startKey);
      }
      profiles=rebuilt;
      const names=Object.keys(profiles);let target=startId?findProfileById(startId):null;
      if(!target&&startKey&&profiles[startKey])target=startKey;
      if(!target&&lastProfile&&profiles[lastProfile])target=lastProfile;
      if(!target&&names.length)target=names.slice().sort((a,b)=>{
        const score=p=>(Math.max(0,Number(p.cur)||0)*1000000)+(Object.keys(p.stars||{}).length*10000)+(Math.max(0,Number(p.researchPoints)||0)*10)+Math.max(0,Number(p.coins)||0);
        return score(profiles[b]||{})-score(profiles[a]||{});
      })[0];
      if(!reconcileContextCurrent())return false;
      if(target){
        if(curProfile!==target)clearTutorialRuntime();
        curProfile=target;lastProfile=target;save=ensureResearchState(Object.assign(defaultSave(),profiles[target]));
        document.body.classList.toggle('nodpad',!save.dpad);setLang(preferredProfileLanguage(save.lang));
      }
      persistAll();updateCoins();updateBadge();refreshSplash();buildProfileSelect();
      if(target)scheduleLeaderboardRepair('safe-account-reconcile',250,true);
      if(!target&&names.length>1){closeModal();show('profile');}
      // Profile listing is a read, not proof that current progress was written.
      // Keep "Saving" until the scheduled core-save/leaderboard repair confirms
      // the write; with no active profile, restore only the last known state.
      if(reconcileContextCurrent()&&!target)setSyncStatus(readLastCloudSync()?'saved':'idle');
      return true;
    }catch(e){
      console.warn('[account] safe reconcile failed',e);
      // R33: listing/reconciling profiles is a read/metadata operation, not a
      // progress-write failure. Do not paint the whole cloud account red when
      // the player's last cloud save is already valid. Real write failures are
      // still surfaced by autosave/saveProgressNow/checkpoint paths.
      if(reconcileContextCurrent()){
        if(navigator.onLine===false)setSyncStatus('offline');
        else if(priorSyncStatus==='error')setSyncStatus('error');
        else setSyncStatus(readLastCloudSync()?'saved':'idle');
      }
      return false;
    }
  })();
  try{return await accountReconcilePromise;}finally{accountReconcilePromise=null;}
}

// Apply the final transaction result to the active device immediately. This
// makes three open platforms converge without requiring a page reload.
window.addEventListener('mx-cloud-profile-merged',ev=>{
  try{
    const detail=ev&&ev.detail||{};if(!detail.profileId||!detail.data)return;
    // The transaction event is emitted asynchronously. Ignore an Apple event
    // after Google/email became active (and vice versa).
    if(detail.accountUid&&String(detail.accountUid)!==currentCloudAuthUid())return;
    const name=findProfileById(detail.profileId);if(!name)return;
    profiles[name]=hasPermanentCloudAccount()?cloudAuthoritativeProfile(profiles[name],detail.data):mergeCloudData(profiles[name],detail.data);
    if(profiles[name]&&profiles[name].profileId)writeAccountProgressVault(profiles[name],profiles[name].profileId);
    if(curProfile===name){save=Object.assign(defaultSave(),profiles[name]);updateCoins();updateBadge();refreshSplash();}
    persistAll();
  }catch(e){console.warn('[account] live cloud merge failed',e);}
});

