function renderFx(t,dt){
  const ambientFx=!document.hidden&&!performanceLow()&&!motionReduced()&&save.effects!==false;
  if(!ambientFx&&!PARTS.length){
    if(fxCanvasDirty){fctx.clearRect(0,0,innerWidth,innerHeight);fxCanvasDirty=false;}
    return;
  }
  fctx.clearRect(0,0,innerWidth,innerHeight);
  fxCanvasDirty=true;
  // ambient dust
  if(ambientFx)for(const d of DUST){
    d.y-=d.v*dt*0.06;if(d.y<-0.02)d.y=1.02;
    const a=0.08+0.07*Math.sin(t/900+d.ph);
    fctx.fillStyle='rgba(190,180,255,'+a+')';
    fctx.beginPath();fctx.arc(d.x*innerWidth+Math.sin(t/1400+d.ph)*8,d.y*innerHeight,d.s,0,7);fctx.fill();
  }
  // lab flask bubble emitters
  if(ambientFx&&t-lastEmit>900){lastEmit=t;
    P({k:'bub',x:innerWidth*0.085,y:innerHeight*0.8,vx:(Math.random()-0.5)*0.4,vy:-0.9,r:1.5+Math.random()*2.5,c:'#a5f06a',life:2.4,amb:1});
    P({k:'bub',x:innerWidth*0.92,y:innerHeight*0.3,vx:(Math.random()-0.5)*0.4,vy:-0.8,r:1.5+Math.random()*2,c:'#7ef0c0',life:2.4,amb:1});
  }
  for(let i=PARTS.length-1;i>=0;i--){
    const p=PARTS[i];p.t+=dt/1000;
    if(p.d&&p.t<p.d)continue;
    const q=p.t/(p.life||1);
    if(q>=1){PARTS.splice(i,1);continue;}
    const dts=dt/16.7;
    fctx.globalAlpha=Math.max(0,(p.amb?0.7:1)*(1-q));
    switch(p.k){
      case 'drop':p.vy+=0.28*dts;p.x+=p.vx*dts;p.y+=p.vy*dts;
        fctx.fillStyle=p.c;fctx.beginPath();fctx.arc(p.x,p.y,p.r,0,7);fctx.fill();break;
      case 'ring':{
        // Portal entry rings shrink inward. Once the radius reaches zero,
        // CanvasRenderingContext2D.arc() throws on a negative radius and can
        // terminate the main RAF loop, leaving portalTransit permanently active.
        // Remove a fully-collapsed/invalid ring before drawing; the visual is
        // already finished at that point and no effect is lost.
        const r=(Number(p.r)||0)+(Number(p.vr2)||0)*p.t;
        if(!Number.isFinite(r)||r<=0){PARTS.splice(i,1);continue;}
        fctx.strokeStyle=p.c;fctx.lineWidth=3.5*(1-q);
        fctx.beginPath();fctx.arc(p.x,p.y,r,0,7);fctx.stroke();break;}
      case 'crys':p.vy+=0.2*dts;p.x+=p.vx*dts;p.y+=p.vy*dts;p.rot+=p.vr*dts;
        fctx.save();fctx.translate(p.x,p.y);fctx.rotate(p.rot);fctx.fillStyle=p.c;
        fctx.fillRect(-p.w/2,-p.w/2,p.w,p.w);fctx.restore();break;
      case 'smoke':p.x+=p.vx*dts;p.y+=p.vy*dts;p.r+=0.22*dts;
        fctx.fillStyle=p.c;fctx.globalAlpha*=0.55;
        fctx.beginPath();fctx.arc(p.x,p.y,p.r,0,7);fctx.fill();break;
      case 'bub':p.x+=(p.vx+Math.sin(p.t*6)*0.5)*dts;p.y+=p.vy*dts;
        fctx.strokeStyle=p.c;fctx.lineWidth=1.6;
        fctx.beginPath();fctx.arc(p.x,p.y,p.r,0,7);fctx.stroke();
        fctx.fillStyle=p.c;fctx.globalAlpha*=0.35;fctx.fill();break;
      case 'pop':{const r=p.r+26*p.t/(p.life);fctx.strokeStyle=p.c;fctx.lineWidth=2.5*(1-q);
        fctx.beginPath();fctx.arc(p.x,p.y,r,0,7);fctx.stroke();break;}
      case 'flame':{p.x+=(p.vx+(Math.random()-0.5)*0.8)*dts;p.y+=p.vy*dts;const r=p.r*(1-q*0.7);
        fctx.fillStyle=p.c;fctx.beginPath();
        fctx.moveTo(p.x,p.y-r*1.7);fctx.quadraticCurveTo(p.x+r,p.y,p.x,p.y+r*0.6);fctx.quadraticCurveTo(p.x-r,p.y,p.x,p.y-r*1.7);fctx.fill();break;}
      case 'squig':p.x+=p.vx*dts;p.y+=(p.vy+Math.sin(p.t*9+p.ph)*1.1)*dts;
        fctx.fillStyle=p.c;fctx.beginPath();fctx.arc(p.x,p.y,p.r,0,7);fctx.fill();break;
      case 'spark':{const ox=p.x,oy=p.y;p.vy+=0.3*dts;p.x+=p.vx*dts;p.y+=p.vy*dts;
        fctx.strokeStyle=p.c;fctx.lineWidth=2;
        fctx.beginPath();fctx.moveTo(ox,oy);fctx.lineTo(p.x,p.y);fctx.stroke();break;}
      case 'streak':{const ox=p.x,oy=p.y;p.x+=p.vx*dts;p.y+=p.vy*dts;const mag=Math.hypot(p.vx,p.vy)||1,nx=p.vx/mag,ny=p.vy/mag,len=(p.len||12)*(1-q*.45);
        fctx.save();fctx.globalCompositeOperation='lighter';fctx.strokeStyle=p.c2||p.c;fctx.lineWidth=(p.w||1.6)*(1-q*.35);fctx.shadowColor=p.c;fctx.shadowBlur=5*(1-q);
        fctx.beginPath();fctx.moveTo(p.x-nx*len,p.y-ny*len);fctx.lineTo(p.x,p.y);fctx.stroke();fctx.restore();break;}
      case 'bond':{
        const local=Math.max(0,Math.min(1,(p.t-(p.d||0))/Math.max(.05,(p.life||1)-(p.d||0))));
        const e=1-Math.pow(1-local,3),xe=p.x1+(p.x2-p.x1)*e,ye=p.y1+(p.y2-p.y1)*e;
        fctx.save();fctx.globalAlpha=Math.sin(local*Math.PI)*.92;
        fctx.strokeStyle=p.c2||'#fff';fctx.lineWidth=(p.w||4)+5;fctx.shadowColor=p.c||'#7ee8ff';fctx.shadowBlur=16*(p.pulse||1);
        fctx.beginPath();fctx.moveTo(p.x1,p.y1);fctx.lineTo(xe,ye);fctx.stroke();
        fctx.shadowBlur=0;fctx.strokeStyle='#fff';fctx.lineWidth=Math.max(1,(p.w||4)*.42);
        fctx.beginPath();fctx.moveTo(p.x1,p.y1);fctx.lineTo(xe,ye);fctx.stroke();fctx.restore();break;}
      case 'sig':{
        const local=Math.max(0,Math.min(1,(p.t-(p.d||0))/Math.max(.05,(p.life||1)-(p.d||0))));
        const pt=mxSigPoint(p,local),prev=mxSigPoint(p,Math.max(0,local-.045));
        fctx.save();fctx.globalAlpha*=Math.sin(Math.min(1,local)*Math.PI);
        fctx.strokeStyle=p.c2||p.c;fctx.lineWidth=Math.max(.7,(p.r||3)*.45*(1-local));
        fctx.beginPath();fctx.moveTo(prev[0],prev[1]);fctx.lineTo(pt[0],pt[1]);fctx.stroke();
        mxDrawSigShape(fctx,p,pt[0],pt[1],local);fctx.restore();break;}
      case 'conf':p.vy+=0.16*dts;p.x+=(p.vx+Math.sin(p.t*5)*0.7)*dts;p.y+=p.vy*dts;p.rot+=p.vr*dts;
        fctx.save();fctx.translate(p.x,p.y);fctx.rotate(p.rot);fctx.fillStyle=p.c;
        fctx.fillRect(-p.w/2,-p.w/4,p.w,p.w/2);fctx.restore();break;
      case 'glit':{p.x+=p.vx*dts;p.y+=p.vy*dts;const a2=0.4+0.6*Math.abs(Math.sin(p.t*10));
        fctx.globalAlpha*=a2;fctx.fillStyle=p.c;
        fctx.save();fctx.translate(p.x,p.y);fctx.rotate(p.t*3);
        fctx.fillRect(-p.r,-0.9,p.r*2,1.8);fctx.fillRect(-0.9,-p.r,1.8,p.r*2);fctx.restore();break;}
    }
    fctx.globalAlpha=1;
  }
}

/* ================= TUTORIAL DEMO (plays out the FULL solve on the REAL board) ================= */
let demoMode=false;
function tutHandTo(gx,gy,show){
  const hand=$('.tutHand');if(!hand)return;
  const r=board.getBoundingClientRect();
  hand.style.left=(r.left+(gx+0.5)*T-19)+'px';
  hand.style.top=(r.top+(gy+0.5)*T-40)+'px';
  hand.style.opacity=show?1:0;
}
function tutSlideDestIn(state,i,d){
  const[dx,dy]=DIRS[d];let x=state[i].x,y=state[i].y;
  while(true){
    const nx=x+dx,ny=y+dy;
    if(grid[ny][nx]||state.some((a,k)=>k!==i&&a.x===nx&&a.y===ny))break;
    x=nx;y=ny;
  }
  return(x===state[i].x&&y===state[i].y)?null:{x,y};
}
function tutIsGoal(state){
  const mnx=Math.min(...state.map(a=>a.x)),mny=Math.min(...state.map(a=>a.y));
  return curMol.key===state.map(a=>a.e+','+(a.x-mnx)+','+(a.y-mny)).sort().join('|');
}
function solveFull(maxDepth){
  const start=atoms.map(a=>({x:a.x,y:a.y,e:a.e}));
  if(tutIsGoal(start))return[];
  let frontier=[{state:start,path:[]}];
  const seen=new Set([start.map(a=>a.x+','+a.y).join('|')]);
  for(let depth=0;depth<maxDepth;depth++){
    const next=[];
    for(const{state,path}of frontier){
      for(let i=0;i<state.length;i++){
        for(let d=0;d<4;d++){
          const dest=tutSlideDestIn(state,i,d);
          if(!dest)continue;
          const ns=state.map((a,k)=>k===i?{x:dest.x,y:dest.y,e:a.e}:a);
          const key=ns.map(a=>a.x+','+a.y).join('|');
          if(seen.has(key))continue;
          seen.add(key);
          const np=[...path,{i,d}];
          if(tutIsGoal(ns))return np;
          next.push({state:ns,path:np});
          if(seen.size>20000)return null;
        }
      }
    }
    frontier=next;
  }
  return null;
}
function runTutorialDemo(){
  if(!(lv===0&&tut===0))return;
  const path=solveFull(LV.p+2);
  if(!path||!path.length)return;
  const savedTut=tut;tut=2;demoMode=true;
  const origAtoms=atoms.map(a=>({x:a.x,y:a.y,e:a.e,ph:a.ph}));
  const origMoves=moves;
  let step=0;
  function playStep(){
    if(step>=path.length){
      setTimeout(()=>{
        tutHandTo(0,0,false);
        setTimeout(()=>{
          atoms.forEach((a,k)=>{a.x=origAtoms[k].x;a.y=origAtoms[k].y;});
          moves=origMoves;hist=[];demoMode=false;tut=0;shake=0;
          updateHUD();
          say(t('tutTurn'),'happy',5000);
        },1000);
      },1000);
      return;
    }
    const{i,d}=path[step];
    const fromX=atoms[i].x,fromY=atoms[i].y;
    tutHandTo(fromX,fromY,true);
    setTimeout(()=>{
      const dest=slideDest(i,d);
      move(i,d);
      const dist=dest?Math.abs(dest.x-fromX)+Math.abs(dest.y-fromY):0;
      if(dest)tutHandTo(dest.x,dest.y,true);
      step++;
      setTimeout(playStep,260+dist*55+180);
    },750);
  }
  playStep();
}

/* R5 ZERO-LOSS PERFORMANCE: automatic governor preserves every visible effect/animation;
   it may only reduce hidden work, internal canvas pixel fill, and non-interactive refresh cost. */
/* ================= MAIN LOOP ================= */
let lastT=performance.now(),perfWindowStart=lastT,perfFrames=0,perfSlowWindows=0,perfGoodWindows=0,perfSevereWindows=0,perfJankFrames=0,perfVeryJankFrames=0,perfSampleLastT=lastT;
const perfGovernorWarmUntil=lastT+6500;
let lastBoardFrame=0,lastGoalFrame=0,lastFxFrame=0;
let mainLoopTimer=0,mainLoopRaf=0,mainLoopNextDue=0;
function cadenceStamp(last,now,every){
  if(!last||now-last>every*4)return now;
  return last+every;
}
const ACTIVE_FRAME_MS=1000/60;
function scheduleMainLoop(cadence=ACTIVE_FRAME_MS,syncToDisplay=false){
  if(mainLoopTimer||mainLoopRaf)return;
  // During live motion/particles, stay on the display's own VSync. Heavy board
  // and FX drawing is still cadence-gated to ~60fps, so a 120/144Hz panel does
  // not double GPU work, while 90Hz panels avoid timeout-to-VSync alias jitter.
  if(syncToDisplay){mainLoopNextDue=0;mainLoopRaf=requestAnimationFrame(loop);return;}
  const now=performance.now(),step=Math.max(16,Number(cadence)||ACTIVE_FRAME_MS);
  if(!mainLoopNextDue||mainLoopNextDue<now-step*2||mainLoopNextDue>now+step*2)mainLoopNextDue=now+step;
  else while(mainLoopNextDue<=now+1)mainLoopNextDue+=step;
  const launch=()=>{mainLoopTimer=0;mainLoopRaf=requestAnimationFrame(loop);};
  const delay=Math.max(0,mainLoopNextDue-now-2);
  if(delay>1)mainLoopTimer=setTimeout(launch,delay);else launch();
}
function wakeMainLoop(){
  if(mainLoopTimer){clearTimeout(mainLoopTimer);mainLoopTimer=0;}
  if(mainLoopRaf){cancelAnimationFrame(mainLoopRaf);mainLoopRaf=0;}
  mainLoopNextDue=0;mainLoopRaf=requestAnimationFrame(loop);
}
function resetPerformanceSampling(t){
  perfWindowStart=t;perfSampleLastT=t;perfFrames=perfJankFrames=perfVeryJankFrames=0;
}
function boardNeedsRealtime(){
  return !!(anim||bounce||nudge||shake>0||won||hintMark||movingWallAnimating||chainAutoActive||reactorActive());
}
function updatePerformanceGovernor(t,expectedCadence=ACTIVE_FRAME_MS){
  if(save.performanceMode!=='auto')return;
  const expected=Math.max(ACTIVE_FRAME_MS,Number(expectedCadence)||ACTIVE_FRAME_MS);
  const gap=Math.max(0,t-perfSampleLastT);perfSampleLastT=t;
  // Ignore cold-start parsing/font/image work; judge the device only after the
  // first menu has settled. This prevents a permanent low-quality first run.
  if(t<perfGovernorWarmUntil){perfWindowStart=t;perfFrames=perfJankFrames=perfVeryJankFrames=0;return;}
  perfFrames++;
  // Jank thresholds scale with the cadence we intentionally requested. An idle
  // 30fps wakeup must not be misclassified as a 60fps frame miss.
  if(gap>expected*1.55)perfJankFrames++;
  if(gap>expected*2.55)perfVeryJankFrames++;
  const span=t-perfWindowStart;
  if(span<2200)return;
  // Normalize observed callbacks against their requested cadence. 30fps idle
  // work at its target is therefore treated as 60/60 health, while real drops
  // during 60fps motion still trigger DPR pressure exactly as before.
  const observed=perfFrames*1000/Math.max(1,span),expectedFps=1000/expected;
  const fps=Math.min(60,observed*(60/expectedFps));
  const jank=perfJankFrames/Math.max(1,perfFrames),veryJank=perfVeryJankFrames/Math.max(1,perfFrames);
  const severe=fps<36||veryJank>.15;
  const slow=fps<50||jank>.16;
  const smooth=fps>56&&jank<.07&&veryJank<.025;
  if(severe)perfSevereWindows=Math.min(5,perfSevereWindows+1);else perfSevereWindows=Math.max(0,perfSevereWindows-1);
  if(slow)perfSlowWindows=Math.min(6,perfSlowWindows+1);else if(smooth)perfSlowWindows=Math.max(0,perfSlowWindows-1);
  perfGoodWindows=smooth?Math.min(8,perfGoodWindows+1):0;
  const hadLow=document.body.classList.contains('mxPerfPressure'),hadSevere=document.body.classList.contains('mxPerfSevere');
  let nextSevere=hadSevere,nextLow=hadLow;
  if(perfSevereWindows>=2){nextSevere=true;nextLow=true;}
  else if(perfSlowWindows>=2)nextLow=true;
  // Recovery is intentionally slower than degradation to prevent quality/FPS
  // oscillation during level transitions or temporary thermal spikes.
  if(hadSevere&&perfGoodWindows>=5){nextSevere=false;perfSevereWindows=0;}
  if(hadLow&&!nextSevere&&perfGoodWindows>=6){nextLow=false;perfSlowWindows=0;}
  if(hadLow!==nextLow||hadSevere!==nextSevere){
    document.body.classList.toggle('mxPerfPressure',nextLow);
    document.body.classList.toggle('mxPerfSevere',nextSevere);
    fxResize();if(scr.game.classList.contains('on'))resize();
  }
  perfFrames=perfJankFrames=perfVeryJankFrames=0;perfWindowStart=t;
}
let duelTensionStage='';
function updateDuelTension(remaining){
  const gameEl=scr&&scr.game?scr.game:null;
  const timer=$('#duelTimer');
  let stage='';
  if(duelMode){
    if(remaining<=10)stage='critical';
    else if(remaining<=20)stage='danger';
    else if(remaining<=30)stage='warning';
  }
  if(stage===duelTensionStage)return;
  duelTensionStage=stage;
  if(gameEl){gameEl.classList.remove('duelTimeWarning','duelTimeDanger','duelTimeCritical');if(stage)gameEl.classList.add('duelTime'+stage.charAt(0).toUpperCase()+stage.slice(1));}
  if(timer)timer.classList.toggle('urgent',stage==='critical');
  if(stage&&duelMode&&!won){
    const seconds=stage==='warning'?30:(stage==='danger'?20:10);
    prop('⏱️ '+seconds+' '+secondsShortLabel(),1050);
    if(stage==='critical')SFX.thunk();
  }
}
function loop(t){
  mainLoopRaf=0;
  // Visibility resume explicitly wakes the loop. Do zero periodic RAF/timer work
  // while backgrounded; this is pure battery/thermal savings with no visible loss.
  if(document.hidden){lastT=t;mainLoopNextDue=0;return;}
  const dt=Math.min(50,t-lastT);lastT=t;
  const gameVisible=scr.game.classList.contains('on');
  const realtimeBoard=gameVisible&&boardNeedsRealtime();
  // R81 battery pass: interactive motion/particles stay display-synced at ~60 fps.
  // A completely static puzzle/menu does not need 30+ JS/GPU wakeups per second.
  // Slow ambient dust/goal wobble remain visible at a battery-friendly cadence,
  // while any move, wall motion, portal animation or particle wakes 60 fps immediately.
  const IDLE_GAME_FRAME_MS=60,IDLE_MENU_FRAME_MS=100;
  const boardEvery=gameVisible?(realtimeBoard?ACTIVE_FRAME_MS:(performanceLow()?90:IDLE_GAME_FRAME_MS)):IDLE_MENU_FRAME_MS;
  const goalEvery=realtimeBoard?(performanceLow()?50:33):(performanceLow()?100:(performancePressure()?80:IDLE_GAME_FRAME_MS));
  const perfCadence=(realtimeBoard||PARTS.length)?ACTIVE_FRAME_MS:(gameVisible?IDLE_GAME_FRAME_MS:IDLE_MENU_FRAME_MS);
  if(gameVisible||PARTS.length)updatePerformanceGovernor(t,perfCadence);else resetPerformanceSampling(t);
  if(gameVisible){
    // Keep interactive puzzle motion at ~60 fps. Automatic pressure changes
    // internal pixel fill / hidden work only; it does not remove visible FX.
    if(t-lastBoardFrame>=boardEvery){lastBoardFrame=cadenceStamp(lastBoardFrame,t,boardEvery);renderBoard(t);}
    if(curMol&&t-lastGoalFrame>=goalEvery){lastGoalFrame=cadenceStamp(lastGoalFrame,t,goalEvery);drawMol($('#goalCv'),curMol,false,t);}
    if((duelMode||crystalMode||chainMode||reactorMode)&&!won&&(!duelMode||!duelState.turnFinished)&&!onlineDuelConnectionPaused()){
      const limit=duelMode?DUEL_TIME_LIMIT:(crystalMode?CRYSTAL_TIME_LIMIT:(chainMode?CHAIN_TIME_LIMIT:REACTOR_TIME_LIMIT));
      const elapsedForTimer=reactorMode?reactorElapsedSeconds(t):(t-levelStartT)/1000;
      const remaining=Math.max(0,limit-elapsedForTimer);
      const txt=duelFormatTime(remaining);
      if(txt!==duelTimerText){
        duelTimerText=txt;const el=$('#duelTimer');
        if(el){el.textContent=txt;} updateDuelTension(remaining);
      }
      if(remaining<=0){if(duelMode)finishDuelTimeout();else if(crystalMode)finishCrystalTimeout();else if(chainMode)finishChainTimeout();else finishReactorTimeout();}
    }
    else if(solveClock.eligible){
      const txt=solveTimeText(solveClockElapsed(t),true);
      if(txt!==duelTimerText){duelTimerText=txt;const el=$('#duelTimer');if(el){el.textContent=txt;el.classList.remove('urgent');}}
    }
  }
  const fxEvery=PARTS.length?(performanceLow()?33:ACTIVE_FRAME_MS):(gameVisible?(performanceLow()?120:(performancePressure()?90:IDLE_GAME_FRAME_MS)):IDLE_MENU_FRAME_MS);
  if(t-lastFxFrame>=fxEvery){const fxDt=Math.min(120,t-lastFxFrame||dt);lastFxFrame=cadenceStamp(lastFxFrame,t,fxEvery);renderFx(t,fxDt);}
  const liveSync=realtimeBoard||PARTS.length>0;
  const staticCadence=gameVisible?Math.min(boardEvery,curMol?goalEvery:999,fxEvery):fxEvery;
  scheduleMainLoop(liveSync?ACTIVE_FRAME_MS:staticCadence,liveSync);
}

/* ================= INPUT ================= */
let pd=null;
function nearestTouchableAtom(clientX,clientY,extra=1){
  const r=board.getBoundingClientRect();
  // Touch geometry must follow the CSS-scaled board, never the internal canvas unit.
  const cellW=r.width/Math.max(1,W),cellH=r.height/Math.max(1,H);
  const finger=(navigator.maxTouchPoints||0)>0;
  // Roughly one full cell on phones. Neighbouring atoms remain deterministic because
  // the nearest normalized centre wins.
  const scale=Math.max(1,Number(extra)||1);
  const rx=Math.max(finger?30:22,cellW*(finger?.92:.72))*scale;
  const ry=Math.max(finger?30:22,cellH*(finger?.92:.72))*scale;
  let best=-1,bestScore=1;
  for(let i=0;i<atoms.length;i++){
    const cx=r.left+(atoms[i].x+.5)*cellW,cy=r.top+(atoms[i].y+.5)*cellH;
    const nx=(clientX-cx)/rx,ny=(clientY-cy)/ry;
    const score=nx*nx+ny*ny;
    if(score<bestScore){bestScore=score;best=i;}
  }
  return best;
}
function atomTouchTapTolerance(pointerType){
  // A finger naturally drifts a few pixels between down/up. Do not turn that
  // small movement into a swipe; mouse/pen remain more precise.
  return pointerType==='touch'?18:(pointerType==='pen'?16:13);
}
board.addEventListener('pointerdown',e=>{
  if(e.isPrimary===false)return;
  if(pd&&pd.id!==e.pointerId)return;
  e.preventDefault();
  try{board.setPointerCapture(e.pointerId);}catch(_){}
  pd={x:e.clientX,y:e.clientY,ai:nearestTouchableAtom(e.clientX,e.clientY),id:e.pointerId,pointerType:e.pointerType||'touch'};
  atomPressIdx=pd.ai;atomPressAt=performance.now();
},{passive:false});
board.addEventListener('pointerup',e=>{
  if(!pd||pd.id!==e.pointerId)return;
  atomPressIdx=-1;
  const dx=e.clientX-pd.x,dy=e.clientY-pd.y;
  const dist=Math.max(Math.abs(dx),Math.abs(dy));
  const tapTol=atomTouchTapTolerance(pd.pointerType);
  if(dist<tapTol){
    if(pd.ai<0)pd.ai=nearestTouchableAtom(e.clientX,e.clientY,1.08);
    if(hammerMode&&!won){const cell=boardCellAt(e.clientX,e.clientY);attemptHammerAt(cell.x,cell.y);pd=null;return;}
    if(barrierMode&&!won){const cell=boardCellAt(e.clientX,e.clientY);attemptBarrierAt(cell.x,cell.y);pd=null;return;}
    if(pd.ai>=0&&!won){
      if(tutorialActive&&tutorialWaitTap!=null&&pd.ai!==tutorialWaitTap){pd=null;return;}
      sel=pd.ai;selT0=performance.now();SFX.select();mxHaptic('light');
      if(effectsAllowed()){
        const br=board.getBoundingClientRect(),cellW=br.width/Math.max(1,W),cellH=br.height/Math.max(1,H),a=atoms[sel],ec=EL[a.e]||{c:'#8fe9ff',hi:'#ffffff'};
        const cx=br.left+(a.x+.5)*cellW,cy=br.top+(a.y+.5)*cellH;
        for(let q=0;q<8;q++)P({k:'glit',x:cx,y:cy,vx:Math.cos(q/8*Math.PI*2)*(.48+Math.random()*.32),vy:Math.sin(q/8*Math.PI*2)*(.48+Math.random()*.32),r:1.2+Math.random()*.8,c:q%3?ec.c:(ec.hi||'#ffffff'),life:.34,d:q*.012});
        P({k:'ring',x:cx,y:cy,r:Math.max(3,T*.055),vr2:Math.max(34,T*.48),c:ec.hi||'#ffffff',life:.18});
      }
      resetIdle();
      if(tut===0){tut=1;say(t('tutSlideMsg'),'happy',4200);}
      if(tutorialActive&&tutorialWaitTap!=null&&pd.ai===tutorialWaitTap){tutorialGoStep(3);}
    }
  }else{
    const d=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?2:0);
    // A swipe may begin near the visual edge of an atom. Recover from the start,
    // midpoint, then release point instead of falling back to an old selection.
    if(pd.ai<0)pd.ai=nearestTouchableAtom(pd.x+dx*.35,pd.y+dy*.35,1.10);
    if(pd.ai<0)pd.ai=nearestTouchableAtom(e.clientX,e.clientY,1.05);
    if(tutorialActive&&tutorialWaitTap!=null){
      if(pd.ai===tutorialWaitTap){sel=pd.ai;selT0=performance.now();SFX.select();tutorialGoStep(3);}
      pd=null;return;
    }
    if(tutorialActive&&[1,2,6,7,9].includes(tutorialStep)){pd=null;return;}
    if(tutorialActive&&tutorialGuideDir!=null&&d!==tutorialGuideDir){pd=null;return;}
    if(pd.ai>=0){
      sel=pd.ai;selT0=performance.now();
      move(sel,d);
    }else{
      // Never move a previously-selected atom when a new swipe did not begin near one.
      mxHaptic('light');
    }
  }
  pd=null;
},{passive:false});
board.addEventListener('pointercancel',e=>{if(pd&&pd.id===e.pointerId){pd=null;atomPressIdx=-1;}},{passive:true});
[['#dU',0],['#dR',1],['#dD',2],['#dL',3]].forEach(([id,d])=>{
  $(id).addEventListener('pointerdown',e=>{e.preventDefault();
    if(tutorialActive&&tutorialWaitTap!=null)return;
    if(tutorialActive&&[1,2,6,7,9].includes(tutorialStep))return;
    if(tutorialActive&&tutorialGuideDir!=null&&d!==tutorialGuideDir)return;
    move(sel,d);
  },{passive:false});
});
